#!/usr/bin/env python3
"""Refresh an offline campaign report from immutable real-run artifacts."""
import argparse,hashlib,html,json
from pathlib import Path

def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def render(root):
 meta=json.loads((root/'campaign.json').read_text());rows=[];done=0
 for r in meta['rounds']:
  r=dict(r);directory=root/r['run'];summary=directory/'summary.json'
  if summary.exists():
   s=json.loads(summary.read_text());r.update(total=s['total'],finished=len(s['cases']),machine_pass=sum(c['machine_pass'] for c in s['cases']),source_sha256=s['build']['source']['sha256'],model=s['model'],parallelism=s.get('observed_parallelism'),elapsed_s=s.get('elapsed_s'),summary_sha256=digest(summary),cases=[{k:c.get(k) for k in ['id','name','machine_pass','elapsed_s','tool_errors','checks','loaded_modules','rubric_review','review_skip_reason','slug']} for c in s['cases']])
   suite=directory.parent/'suite.json'
   versions={c['id']:c.get('case_version',1) for c in json.loads(suite.read_text())['cases']} if suite.exists() else {}
   for c in r['cases']:c['case_version']=versions.get(c['id']);c['path']=r['run']+'/cases/'+c['slug']
   genuine=s.get('mode')=='live' and not s.get('reassessment') and not s.get('external_review')
   # Completed errors stay visible; an all-infrastructure failure is not a round.
   executed=any(c.get('result',{}).get('events') for c in s['cases'])
   if s.get('complete') and genuine and executed:
    r['status']='complete';done+=1
   elif s.get('complete'):r['status']='infrastructure-failure'
   else:r['status']='running'
  analysis=root/r.get('analysis',str(directory.parent.relative_to(root)/'analysis.md'))
  if analysis.exists():r['analysis_text']=analysis.read_text()
  rows.append(r)
 data={**meta,'completed_rounds':done,'rounds':rows}
 (root/'campaign-summary.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
 page='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>游戏生成器 · 迭代评测</title><style>\n:root{--paper:#f3efe5;--ink:#223b32;--muted:#667468;--line:#cecdbc;--accent:#3f6752;--fail:#8b4331}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1150px;margin:auto;padding:42px 28px}header{border-bottom:2px solid var(--ink);padding-bottom:24px}small,label{color:var(--muted)}h1{font-size:38px;letter-spacing:-1px;margin:6px 0}h2{font-size:23px;margin:24px 0 10px}p{max-width:800px}nav{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin:24px 0}select{font:inherit;padding:6px;background:transparent;border:1px solid var(--line);color:var(--ink)}.progress{display:flex;gap:5px;margin:15px 0}.progress span{width:38px;height:7px;background:var(--line)}.progress .done{background:var(--accent)}section{padding:20px 0;border-top:1px solid var(--line)}.meta{font-size:13px;color:var(--muted)}.case{display:grid;grid-template-columns:minmax(180px,1fr) 90px 85px 2fr;gap:14px;padding:12px 0;border-bottom:1px solid var(--line)}.pass{color:var(--accent)}.fail{color:var(--fail)}a{color:inherit;text-underline-offset:3px}pre{white-space:pre-wrap;font:14px/1.65 inherit;background:#eae8da;padding:18px;max-height:550px;overflow:auto}details{padding-top:6px}summary{cursor:pointer}.status{font-variant-numeric:tabular-nums}.bars{display:grid;gap:8px;margin:14px 0 22px}.bar{display:grid;grid-template-columns:55px minmax(80px,1fr) 70px;gap:10px;align-items:center;font-size:13px}.track{display:flex;background:var(--line);height:11px}.track .ok{background:var(--accent)}.track .bad{background:var(--fail)}.matrix{overflow:auto}table{border-collapse:collapse;font-size:13px;min-width:760px;width:100%}th,td{padding:9px 7px;border-bottom:1px solid var(--line);text-align:center}th:first-child,td:first-child{text-align:left}.empty{color:var(--muted)}.conclusions{padding:18px 0}.conclusions li{margin:8px 0}footer{border-top:2px solid var(--ink);margin-top:30px;padding-top:20px;color:var(--muted)}@media(max-width:700px){main{padding:24px 16px}h1{font-size:29px}.case{grid-template-columns:1fr 70px}.case .checks{grid-column:1/-1} }\n</style><main><header><small>WORKSHOP / LIVE AGENT EVALUATION</small><h1>用失败证据推进游戏质量</h1><div id="count"></div><div id="progress" class="progress"></div><p>真实生成、工具轨迹、严格 VM 规则分别留档。基础检查通过只覆盖列出的规则；模型审阅单独显示，不代表实际试玩质量。版本不同的案例不合并比较。</p></header><section class="conclusions"><h2>实施结果与已知限制</h2><ul><li>默认 Skill 保持精简，玩法、输入、音乐、3D 和性能按模块读取；每轮源码与用例固定留档。</li><li>已修复只检查误触发发布、畸形工具参数导致历史投影崩溃、输出预算耗尽错误分类；保留 500000 上下文窗口。</li><li>严格 VM 检查覆盖输入边沿、重开/剩余生命、精确修改、素材保留、音乐节奏、P8 定点计时和方向；基础通过不能替代完整试玩。</li><li>长思考无产物、15分钟超时、3D运行崩溃和测评误报均保留原失败记录；不能据此宣称复杂游戏生成稳定成功。</li></ul><a href="completion-audit.json">最终验证与部署凭据</a></section><nav><label>轮次 <select id="round"><option value="">全部轮次</option></select></label><label>结果 <select id="result"><option value="">全部案例</option><option value="fail">仅规则失败</option><option value="pass">仅规则通过</option></select></label><a href="campaign-summary.json">原始汇总 JSON</a></nav><div id="coverage"></div><div id="rounds"></div><footer>仍需掌机实际试玩确认：画面可读性、操作手感、音乐听感和整机帧稳定性。Mac 回放耗时不能替代掌机前端性能。</footer></main><script id="data" type="application/json">PAYLOAD</script><script>\nconst data=JSON.parse(document.getElementById(\'data\').textContent),root=document.getElementById(\'rounds\');\nfunction el(tag,text,cls){let e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}\nfunction link(text,path){let a=el(\'a\',text);a.href=path;return a}\ndocument.getElementById(\'count\').textContent=`已完成 ${data.completed_rounds} 轮真实评测（目标至少 ${data.minimum_rounds} 轮） · ${data.model}`;\nfor(let i=0;i<Math.max(data.minimum_rounds,data.completed_rounds);i++)document.getElementById(\'progress\').append(el(\'span\',undefined,i<data.completed_rounds?\'done\':\'\'));\nfor(const r of data.rounds){let o=el(\'option\',`第 ${r.round} 轮 · ${r.focus}`);o.value=r.round;document.getElementById(\'round\').append(o)}\nconst coverage=document.getElementById(\'coverage\');coverage.append(el(\'h2\',\'每轮规则结果\'),el(\'small\',\'案例组合各轮不同；柱图显示已完成规则数量，不代表综合游戏质量。绿色通过，红色失败。\'));\nlet bars=el(\'div\',undefined,\'bars\');for(const r of data.rounds){let row=el(\'div\',undefined,\'bar\'),track=el(\'div\',undefined,\'track\'),ok=el(\'span\',undefined,\'ok\'),bad=el(\'span\',undefined,\'bad\');ok.style.width=((r.machine_pass??0)/Math.max(1,r.total??1)*100)+\'%\';bad.style.width=(((r.finished??r.total??0)-(r.machine_pass??0))/Math.max(1,r.total??1)*100)+\'%\';row.append(el(\'span\',\'第\'+r.round+\'轮\'),track,el(\'span\',`${r.machine_pass??0}/${r.total??\'—\'}`));track.append(ok,bad);bars.append(row)}coverage.append(bars);\nlet keys=new Map();for(const r of data.rounds)for(const c of r.cases??[]){let key=c.id+\'@\'+c.case_version;keys.set(key,{id:c.id,version:c.case_version,name:c.name})}let repeated=[...keys.values()].filter(k=>data.rounds.filter(r=>(r.cases??[]).some(c=>c.id===k.id&&c.case_version===k.version)).length>1);if(repeated.length){coverage.append(el(\'h2\',\'同案例版本复测\'),el(\'small\',\'表中只合并相同案例版本；仍以每轮源码、评测器哈希及分析解释差异。\'));\nlet wrap=el(\'div\',undefined,\'matrix\'),table=el(\'table\'),head=el(\'tr\');head.append(el(\'th\',\'案例 / 版本\'));for(const r of data.rounds)head.append(el(\'th\',String(r.round)));table.append(head);for(const key of repeated){let row=el(\'tr\');row.append(el(\'td\',key.name+\' v\'+key.version));for(const r of data.rounds){let c=(r.cases??[]).find(c=>c.id===key.id&&c.case_version===key.version);row.append(el(\'td\',c?(c.machine_pass?\'通过\':\'失败\'):\'—\',c?(c.machine_pass?\'pass\':\'fail\'):\'empty\'))}table.append(row)}wrap.append(table);coverage.append(wrap)}\nfunction draw(){root.replaceChildren();for(const r of data.rounds){if(document.getElementById(\'round\').value&&r.round!=document.getElementById(\'round\').value)continue;let s=el(\'section\');s.append(el(\'h2\',`${String(r.round).padStart(2,\'0\')} / ${r.focus}`));s.append(el(\'div\',`${r.status} · ${r.machine_pass??0}/${r.total??\'?\'} 规则通过 · 并行 ${r.parallelism??\'—\'} · 源码 ${(r.source_sha256??\'\').slice(0,12)}`,\'meta\'));s.append(link(\'本轮完整报告\',r.run+\'/report.html\'));for(const c of r.cases??[]){let filter=document.getElementById(\'result\').value;if(filter&&(filter===\'pass\')!==c.machine_pass)continue;let line=el(\'div\',undefined,\'case\');line.append(link(c.name+` · v${c.case_version}`,c.path+\'/game.lua\'),el(\'span\',c.machine_pass?\'规则通过\':\'规则失败\',c.machine_pass?\'pass\':\'fail\'),el(\'span\',`${Math.round(c.elapsed_s)} 秒`,\'status\'));let checks=el(\'div\',undefined,\'checks\');let failed=(c.checks??[]).filter(x=>!x.ok);checks.append(el(\'div\',failed.length?failed.map(x=>x.name+(x.reason?\'：\'+x.reason:\'\')).join(\'；\'):\'列出的客观检查通过\'));let review=c.rubric_review;checks.append(el(\'small\',review?(review.ok?`模型审阅格式有效${review.repair_attempted?\'（修正一次）\':\'\'}，结论需复核`:\'模型审阅无效，未计分\'):(c.review_skip_reason??\'未请求模型审阅\')));checks.append(document.createTextNode(\' · \'),link(\'轨迹\',c.path+\'/trace.json\'));line.append(checks);s.append(line)}if(r.analysis_text){let d=el(\'details\');d.append(el(\'summary\',\'发现、修正与回归依据\'),el(\'pre\',r.analysis_text));s.append(d)}root.append(s)}}\nfor(const id of [\'round\',\'result\'])document.getElementById(id).addEventListener(\'change\',draw);draw();\n</script></html>'
 page=page.replace('PAYLOAD',payload)
 (root/'report.html').write_text(page)
 print(str(root/'report.html'))
 return data
if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('root',type=Path);a=p.parse_args();render(a.root.resolve())
